import{describe,it,expect}from"vitest";const REQUIRED_FIELDS=["id","name","path","capital","food","festival","description","story"];describe("mapData.locations — state data integrity",()=>{it("has exactly 36 state entries",()=>{expect(mapData.locations).toHaveLength(36)}),it("every state has all required fields",()=>{mapData.locations.forEach(t=>{REQUIRED_FIELDS.forEach(e=>{expect(t).toHaveProperty(e)})})}),it("every required field is a non-empty string",()=>{mapData.locations.forEach(t=>{REQUIRED_FIELDS.forEach(e=>{expect(typeof t[e]).toBe("string"),expect(t[e].trim().length).toBeGreaterThan(0)})})}),it("all state IDs are unique",()=>{const t=mapData.locations.map(t=>t.id);expect(new Set(t).size).toBe(t.length)}),it("all state names are unique",()=>{const t=mapData.locations.map(t=>t.name);expect(new Set(t).size).toBe(t.length)}),it("every SVG path data is a non-empty string (valid SVG path syntax)",()=>{mapData.locations.forEach(t=>{expect(t.path.length).toBeGreaterThan(10),expect(t.path.trim().charAt(0).toLowerCase()).toBe("m")})}),it("every description is a substantial sentence (>20 chars)",()=>{mapData.locations.forEach(t=>{expect(t.description.length).toBeGreaterThan(20)})}),it("every story includes the capital name",()=>{mapData.locations.forEach(t=>{expect(t.story).toContain(t.capital)})}),it("state lookup by id returns the correct state",()=>{const t=t=>mapData.locations.find(e=>e.id===t);expect(t("mh").name).toBe("Maharashtra"),expect(t("dl").name).toBe("Delhi"),expect(t("tn").name).toBe("Tamil Nadu"),expect(t("rj").name).toBe("Rajasthan"),expect(t("wb").name).toBe("West Bengal")}),it("mapData has a valid viewBox string",()=>{expect(mapData.viewBox).toMatch(/^\d+\s+\d+\s+\d+\s+\d+$/)}),it("all state IDs are 2-letter lowercase codes",()=>{mapData.locations.forEach(t=>{expect(t.id).toMatch(/^[a-z]{2}$/)})}),it("food and festival are distinct from state name",()=>{mapData.locations.forEach(t=>{expect(t.food).not.toBe(t.name),expect(t.festival).not.toBe(t.name)})})});